contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address spender, uint256 amount) public payable {
        require(spender != address(0));
        require(amount != 0);

        address owner = address(this);
        uint256 spenderBefore = c.balanceOf(spender); if (__ESBMC_reverted()) return;
        uint256 ownerBefore = c.balanceOf(owner); if (__ESBMC_reverted()) return;

        bool reverted;
        c.approve(spender, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 allowanceAfter = c.allowance(owner, spender); if (__ESBMC_reverted()) return;
        uint256 spenderAfter = c.balanceOf(spender); if (__ESBMC_reverted()) return;
        uint256 ownerAfter = c.balanceOf(owner); if (__ESBMC_reverted()) return;

        assert(!reverted && allowanceAfter == amount && spenderAfter == spenderBefore && ownerAfter == ownerBefore);
    }

    receive() external payable {}
}

